(async () => {
  const w_slots = {
  "list": [
    1,
    2,
    3,
    4
  ],
  "divisor": 2
};
  const w_answer = await (async () => {
const slots = w_slots;
const kept = slots.list.filter((value) => value % slots.divisor === 0);
return kept.length + " elements.";
  })();
  console.log(String(w_answer));
})();

