(async () => {
  const w_slots = {
  "list": [
    1,
    2,
    3,
    4
  ],
  "start": 0
};
  const w_answer = await (async () => {
const slots = w_slots;
const reduce = (list, start) => {
  let sum = start;
  for (const value of list) {
    sum += value;
  }
  return sum;
};
return String(reduce(slots.list, slots.start));
  })();
  console.log(String(w_answer));
})();

